#!/usr/bin/env python3
"""gen_dispatch.py: the indirect-call dispatch table over a set of translated VAs.

gen_translated.py writes the committed table (src/pes/translated/pes_dispatch_gen.hpp);
driver.py writes the same header into each diff build's tree.
"""
import argparse


def norm(vas):
    return sorted({"0x" + v.lower().replace("0x", "").upper() for v in vas})


def text(vas):
    """The dispatch header: each VA maps to its translated function; a target outside the table aborts loudly."""
    vas = norm(vas)
    L = [
        "// Generated by tools/dev/translate/gen_dispatch.py: PES VA ->",
        "// translated-function table. Do not edit.",
        "#pragma once",
        "#include <cstdio>",
        "#include <cstdlib>",
        '#include "pes_state.hpp"',
        '#include "pes_dispatch.hpp"',
    ]
    for v in vas:
        L.append("void pes_fn_%s(PesState& s);" % v[2:])
    L.append("inline PesDispatch pes_dispatch_lookup(uint64_t t) {")
    L.append("  switch (t) {")
    for v in vas:
        L.append("    case 0x%sULL: return {pes_fn_%s};" % (v[2:], v[2:]))
    L.append("    default: return {0};")
    L.append("  }")
    L.append("}")
    L.append("[[noreturn]] inline void pes_dispatch_missing(uint64_t t) {")
    L.append('  std::fprintf(stderr, "PES_DISPATCH_UNTRANSLATED: %#llx\\n",')
    L.append("               (unsigned long long)t);")
    L.append("  std::abort();")
    L.append("}")
    return "\n".join(L) + "\n"


def write(out, vas):
    """Write <out>/pes_dispatch_gen.hpp; returns the target count."""
    vas = norm(vas)
    with open(out.rstrip("/") + "/pes_dispatch_gen.hpp", "w") as f:
        f.write(text(vas))
    return len(vas)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", required=True)
    ap.add_argument("--vas", nargs="*", default=[])
    args = ap.parse_args()
    n = write(args.out, args.vas)
    print("wrote %s/pes_dispatch_gen.hpp (%d targets)" % (args.out, n))


if __name__ == "__main__":
    import sys
    sys.exit(main())
